def retry(fn, attempts=5, base=0.5, cap=8.0, sleep=lambda s: None, rng=lambda hi: hi):
    last = None
    for n in range(attempts):
        try:
            return fn()
        except ConnectionError as e:
            last = e
            if n == attempts - 1:
                break
            delay = rng(min(cap, base * 2 ** n))
            print(f"attempt {n + 1} failed, sleeping {delay:.1f}s")
            sleep(delay)
    raise last

calls = {"n": 0}
def flaky():
    calls["n"] += 1
    if calls["n"] < 3:
        raise ConnectionError("boom")
    return "ok"

print(retry(flaky))
print("calls", calls["n"])
def always():
    raise ConnectionError("down")
try:
    retry(always, attempts=3)
except ConnectionError as e:
    print("gave up:", e)

import re
UNITS = {"s": 1, "m": 60, "h": 3600, "d": 86400}
FULL = re.compile(r"(?:\d+[smhd])+")
PART = re.compile(r"(\d+)([smhd])")
def to_seconds(text):
    if not FULL.fullmatch(text):
        raise ValueError(f"bad duration: {text!r}")
    return sum(int(n) * UNITS[u] for n, u in PART.findall(text))
retention = ["2d", "1h30m", "45s", "90m", "1d12h"]
for t in sorted(retention, key=to_seconds):
    print(t, to_seconds(t))
for bad in ["", "5", "1x5m", "1h 30m"]:
    try:
        to_seconds(bad)
    except ValueError as e:
        print("error:", e)

class Breaker:
    def __init__(self, threshold, cooldown, clock):
        self.threshold, self.cooldown, self.clock = threshold, cooldown, clock
        self.state, self.fails, self.opened_at = "closed", 0, None
    def call(self, fn):
        if self.state == "open":
            if self.clock() - self.opened_at >= self.cooldown:
                self.state = "half-open"
            else:
                return "fast-fail"
        try:
            r = fn()
        except Exception:
            self.fails += 1
            if self.state == "half-open" or self.fails >= self.threshold:
                self.state, self.opened_at = "open", self.clock()
            return "error"
        self.state, self.fails = "closed", 0
        return r

